WITH metrics AS (SELECT id, store_name, city, region, opened_date, sqft, ROUND(sqft / SUM(sqft) OVER (PARTITION BY region), 4) sqft_share, AVG(sqft) OVER (PARTITION BY region ORDER BY sqft, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) sqft_avg_5_prior, CUME_DIST() OVER (ORDER BY sqft NULLS FIRST) sqft_cume_dist FROM stores), deduped AS (SELECT * FROM metrics QUALIFY ROW_NUMBER() OVER (PARTITION BY city ORDER BY sqft DESC NULLS LAST, id) = 1), ranked AS (SELECT * FROM deduped QUALIFY RANK() OVER (PARTITION BY region ORDER BY opened_date DESC) = 1), matched_keys AS (SELECT city FROM ranked EXCEPT ALL SELECT city FROM stores WHERE sqft BETWEEN 8080 AND 12674), verified AS (SELECT s.* FROM ranked s JOIN matched_keys k ON s.city = k.city), eligible AS (SELECT s.* FROM verified s WHERE EXISTS (SELECT 1 FROM store_sales c WHERE c.store_id = s.id AND c.sale_date < '2024-05-01')), metrics_stores AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY city ORDER BY sqft NULLS LAST) sqft_percent_rank, ROUND(sqft / SUM(sqft) OVER (PARTITION BY region), 4) sqft_share_2 FROM eligible), kept_keys AS (SELECT city, id FROM metrics_stores EXCEPT ALL SELECT city, id FROM stores WHERE sqft BETWEEN 8928 AND 13309), reconciled AS (SELECT s.* FROM metrics_stores s JOIN kept_keys k ON s.city = k.city AND s.id = k.id) SELECT region, PERCENTILE_APPROX(sqft_percent_rank, ARRAY(0.25, 0.5, 0.75)) AS sqft_percent_rank_quartiles, COUNT(DISTINCT id) AS distinct_ids, BIT_OR(sqft) AS sqft_bit_or, SORT_ARRAY(COLLECT_SET(region)) AS region_list, BIT_AND(sqft) AS sqft_bit_and, SUM(CASE WHEN city = 'Berlin' THEN sqft_percent_rank ELSE 0 END) AS berlin_sqft_percent_rank FROM reconciled GROUP BY region
